      "tiers": [
        {
          "id": "volume.weighted_reps:t1",
          "title": "Фундамент из повторений",
          "phrase": "В твоей истории уже 100 повторений с сохранённым весом больше нуля. Первый ряд железной плотины на месте!",
          "imagePrompt": "An industrious beaver with a broad paddle tail rolls a dumbbell into a low dam foundation across a narrow stream. Two more dumbbells lie neatly beside a wooden wheelbarrow, while a curious duck watches from the opposite bank.",
          "fishMarkup": "[warm] В твоей истории уже 100 повторений с сохранённым весом больше нуля. [playful] Первый ряд железной плотины на месте!",
          "audioText": "В твоей истории уже 100 повторений с сохранённым весом больше нуля. Первый ряд железной плотины на месте!"
        },
        {
          "id": "volume.weighted_reps:t2",
          "title": "Плотина набирает размах",
          "phrase": "Ты накопил 500 повторений с сохранённым весом больше нуля. Плотина растёт, бобр уже ходит с видом главного инженера.",
          "imagePrompt": "The same broad-tailed beaver stands on a scaffold beside a growing dam made of interlocked dumbbells. Holding a wooden mallet, it inspects the upper row with exaggerated seriousness as the duck tests the rising water behind the structure.",
          "fishMarkup": "[confident] Ты накопил <emphasis>500 повторений</emphasis> с сохранённым весом больше нуля. [playful] Плотина растёт, бобр уже ходит с видом главного инженера.",
          "audioText": "Ты накопил 500 повторений с сохранённым весом больше нуля. Плотина растёт, бобр уже ходит с видом главного инженера."
        },
        {
          "id": "volume.weighted_reps:t3",
          "title": "Утка требует аквапарк",
          "phrase": "В твоей копилке 1500 повторений с сохранённым весом больше нуля. Железная плотина готова — утка требует аквапарк.",
          "imagePrompt": "The broad-tailed beaver unveils a towering dumbbell dam with a curling water chute built into its spillway. The duck eagerly waits at the chute entrance with a tiny swimming ring, while the beaver stares at an enormous queue of ducklings.",
          "fishMarkup": "[triumphant] В твоей копилке <emphasis>1500 повторений</emphasis> с сохранённым весом больше нуля. Железная плотина готова — <slow>утка требует аквапарк.</slow>",
          "audioText": "В твоей копилке 1500 повторений с сохранённым весом больше нуля. Железная плотина готова — утка требует аквапарк."
        }
      ]
    },
    {
      "id": "volume.volume_days",
      "tiers": [
        {
          "id": "volume.volume_days:t1",
          "title": "Лейка выходит на участок",
          "phrase": "Ты накопил 3 дня с учтённым объёмом больше нуля. Лейка вышла на участок и уже командует тремя ростками.",
          "imagePrompt": "A squat enamel watering can with little boots and expressive eyes tends three seedlings in separate square pots. It raises its spout like a tiny foreman giving instructions, with a small trowel resting across a crate beside the pots.",
          "fishMarkup": "[warm] Ты накопил 3 дня с учтённым объёмом больше нуля. [playful] Лейка вышла на участок и уже командует тремя ростками.",
          "audioText": "Ты накопил 3 дня с учтённым объёмом больше нуля. Лейка вышла на участок и уже командует тремя ростками."
        },
        {
          "id": "volume.volume_days:t2",
          "title": "Подоконник больше не справляется",
          "phrase": "В твоей истории 10 дней с учтённым объёмом больше нуля, не обязательно подряд. Лейка уже заведует целой оранжереей.",
          "imagePrompt": "The same booted enamel watering can strides down the aisle of a compact greenhouse containing ten square plant pots on stepped shelves. Its long spout reaches an upper seedling while curling vines spill through the open doorway.",
          "fishMarkup": "[confident] В твоей истории <emphasis>10 дней</emphasis> с учтённым объёмом больше нуля, не обязательно подряд. [playful] Лейка уже заведует целой оранжереей.",
          "audioText": "В твоей истории 10 дней с учтённым объёмом больше нуля, не обязательно подряд. Лейка уже заведует целой оранжереей."
        },
        {
          "id": "volume.volume_days:t3",
          "title": "Повышение до фонтана",
          "phrase": "У тебя уже 25 дней с учтённым объёмом больше нуля. Сад разросся так, что лейка повысила себя до фонтана.",
          "imagePrompt": "The booted enamel watering can reclines proudly in a deckchair at the center of a lush greenhouse garden. Water arcs from its spout into branching irrigation channels feeding twenty-five square pots, while its boots dangle over the chair edge.",
          "fishMarkup": "[triumphant] У тебя уже <emphasis>25 дней</emphasis> с учтённым объёмом больше нуля. Сад разросся так, что <slow>лейка повысила себя до фонтана.</slow>",
          "audioText": "У тебя уже 25 дней с учтённым объёмом больше нуля. Сад разросся так, что лейка повысила себя до фонтана."
        }
      ]
    }
  ]
